      SUBROUTINE FOCUS2CC     CALCULATES SECOND-ORDER TRANSFER MATRIX FOR A QUADRUPOLEC      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM5A.CIN'      INCLUDE 'ELM5B.CIN'      INCLUDE 'R.CIN'      INCLUDE 'T.CIN'C      J = JQUAD      CS = R(J,J)      SN = R(J,J+1)      T(J,J+15) = 0.5*KQ2*SN*L      T(J+1,J+16) = 0.5*KQ2*SN*L      T(J,J+16) = (SN - L*CS)/2.0      T(J+1,J+15) = KQ2*(SN + L*CS)/2.0      T(5,J*(J+1)/2) = - 0.25*KQ2*(L - SN*CS)      T(5,J*(J+3)/2) = 0.5*KQ2*SN**2      T(5,J*(J+3)/2+1) = - 0.25*(L + CS*SN)      RETURN      END